<?php
define('ABSPATH',__DIR__.'/');
class WP_Error {public $message;function __construct($c,$m,$d=null){$this->message=$m;}}
function is_wp_error($v){return $v instanceof WP_Error;}
function sanitize_text_field($v){return trim(strip_tags($v));}function sanitize_textarea_field($v){return trim(strip_tags($v));}
function get_option($k,$d=array()){return $GLOBALS['opts'][$k]??$d;}function update_option($k,$v,$a=false){$GLOBALS['opts'][$k]=$v;return true;}
function wp_json_encode($s){return json_encode($s);}function wp_generate_uuid4(){return sprintf('aaaaaaaa-0000-4000-8000-%012d',++$GLOBALS['uuid']);}function wp_mkdir_p($d){return is_dir($d)||mkdir($d,0700,true);}
class SBS_Finishing {static function error($c,$m,$s=422){return new WP_Error($c,$m,array('status'=>$s));}}
class SBS_Final_Print {static function intact($a){return is_file($a['path'])&&hash_file('sha256',$a['path'])===$a['sha256'];}}
class SBS_Storage {static $assets=array();static function base_dir(){return $GLOBALS['tmp'];}static function ensure_directories(){return true;}static function absolute_path($a){return $a['path'];}static function get_asset($id){return self::$assets[$id]??null;}static function store_bytes($bytes,$name,$mime,$owner,$owner_id,$role,$label){$id=count(self::$assets)+1;$path=self::base_dir().'/asset-'.$id.'.png';file_put_contents($path,$bytes);return self::$assets[$id]=array('id'=>$id,'filename'=>$name,'mime'=>$mime,'role'=>$role,'path'=>$path,'sha256'=>hash('sha256',$bytes),'url'=>'/asset/'.$id);}static function store_upload($f,$o,$id,$r,$label){return self::store_bytes(file_get_contents($f['tmp_name']),$f['name']??'mask.png','image/png',$o,$id,$r,$label);}}
class SBS_OpenAI {static $submits=0;static $polls=0;static $uncertain=false;static function submit_image($p,$ids,$options){self::$submits++;check($options['purpose']==='mockup_outpaint','Photo instruction isolation missing');return self::$uncertain?array():array('id'=>'provider-id');}static function poll($id){self::$polls++;return array();}static function is_configured(){return false;}static function parse_image_response($r){if(self::$polls===1)return array('status'=>'in_progress');$im=new Imagick();$im->newImage(50,70,'green','png');return array('status'=>'completed','bytes'=>$im->getImageBlob());}}
class Q {private $p,$files;function __construct($p,$files=array()){$this->p=$p;$this->files=$files;}function get_param($k){return $this->p[$k]??null;}function get_file_params(){return $this->files;}}
function check($v,$m){if(!$v)throw new Exception($m);}
require dirname(__DIR__).'/includes/class-sbs-mockups.php';
$GLOBALS['tmp']=sys_get_temp_dir().'/sbs-mockups-'.bin2hex(random_bytes(5));mkdir($GLOBALS['tmp']);$GLOBALS['uuid']=0;
try{
 foreach(range(0,8) as $a){$f=SBS_Mockups::frame(120,100,.5625,$a);check($f['protected_width']===120&&$f['protected_height']===100,'Source dimensions changed');check($f['y']===(int)round(($f['height']-100)*floor($a/3)/2),'Anchor direction wrong');}
 check(is_wp_error(SBS_Mockups::frame(120,100,.1,4)),'Invalid ratio accepted');check(is_wp_error(SBS_Mockups::frame(120,100,1,9)),'Invalid anchor accepted');
 check(is_wp_error(SBS_Mockups::calibration(array('quad'=>array(array(0,0),array(1,1),array(1,0),array(0,1))))),'Crossing print corners accepted');
 $a=array('sha256'=>'one');$r=array('final_print'=>array('finished'=>array('asset'=>$a,'approval'=>array('sha256'=>'other'))));check(SBS_Mockups::artwork($r)===null,'Unapproved asset offered');$r['final_print']['finished']['approval']['sha256']='one';check(SBS_Mockups::artwork($r)===$a,'Approved artwork missing');
 $im=new Imagick();$im->newImage(120,100,new ImagickPixel('transparent'),'png');$draw=new ImagickDraw();$draw->setFillColor('rgba(220,230,240,0.6)');$draw->rectangle(1,1,119,99);$draw->setFillColor('red');$draw->rectangle(10,10,40,50);$im->drawImage($draw);$im->setImageAlphaChannel(Imagick::ALPHACHANNEL_ACTIVATE);$im->setImageFormat('png32');$source=SBS_Storage::store_bytes($im->getImageBlob(),'photo.png','image/png','mockups',0,'mockup_template','Test white shirt');$im->clear();
 // A lost upload response reuses the same immutable photo with the same request key.
 $uploadFile=array('tmp_name'=>$source['path'],'name'=>'white-shirt.png','size'=>filesize($source['path']),'error'=>0);
 $uq=new Q(array('kind'=>'template','request_id'=>'cccccccc-0000-4000-8000-000000000001'),array('file'=>$uploadFile));
 $first=SBS_Mockups::upload($uq);check(!is_wp_error($first),'Photo import failed');$assetCount=count(SBS_Storage::$assets);$retry=SBS_Mockups::upload($uq);check($retry['asset']['id']===$first['asset']['id']&&count(SBS_Storage::$assets)===$assetCount,'Photo retry duplicated its source');
 $q=new Q(array('job'=>'bbbbbbbb-0000-4000-8000-000000000001','operation'=>'start','asset_id'=>$source['id'],'mode'=>'smart','ratio'=>.5625,'anchor'=>2,'consent'=>true));
 $start=SBS_Mockups::expand($q);check(!is_wp_error($start),is_wp_error($start)?$start->message:'');check($start['status']==='processing','Start failed');check(SBS_OpenAI::$submits===1,'Generation not submitted exactly once');
 SBS_Mockups::expand($q);check(SBS_OpenAI::$submits===1,'Retry submitted paid work twice');
 $done=SBS_Mockups::expand(new Q(array('job'=>'bbbbbbbb-0000-4000-8000-000000000001','operation'=>'poll')));check($done['status']==='complete','Poll failed');$f=$done['frame'];$out=new Imagick($done['asset']['path']);$out->cropImage(120,100,$f['x'],$f['y']);$out->setImagePage(0,0,0,0);$original=new Imagick($source['path']);$diff=$original->compareImages($out,Imagick::METRIC_MEANABSOLUTEERROR);check($diff[1]===0.0,'Original photo pixels/alpha were redrawn: MAE '.$diff[1]);$original->clear();$out->clear();$diff[0]->clear();
 $again=SBS_Mockups::expand($q);check($again['asset']['sha256']===$done['asset']['sha256']&&SBS_OpenAI::$polls===2,'Completed output not reused');check(hash_file('sha256',$source['path'])===$source['sha256'],'Source overwritten');
 SBS_OpenAI::$uncertain=true;$before=SBS_OpenAI::$submits;$u=new Q(array('job'=>'bbbbbbbb-0000-4000-8000-000000000002','operation'=>'start','asset_id'=>$source['id'],'mode'=>'scene','ratio'=>1.9,'anchor'=>0,'consent'=>true));check(is_wp_error(SBS_Mockups::expand($u)),'Unknown submit called success');check(is_wp_error(SBS_Mockups::expand($u)),'Unknown submit auto-retried');check(SBS_OpenAI::$submits===$before+1,'Duplicate uncertain paid work');
 echo "Mock-ups PHP: validation, approval filtering, protected source/alpha, nine anchors, idempotent expansion/poll/reload and uncertain-submit refusal passed.\n";
}finally{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($GLOBALS['tmp'],FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $file){$file->isDir()?rmdir($file->getPathname()):unlink($file->getPathname());}rmdir($GLOBALS['tmp']);}
